"""Editable generic animation example. Generated by create_animation_kit; no private assets."""
import json
from pathlib import Path
import bpy
from openkatana import blender_helpers as H

ROOT = Path(__file__).resolve().parent
C = json.loads((ROOT/'config.json').read_text(encoding='utf8'))
bpy.ops.object.select_all(action='SELECT')
bpy.ops.object.delete(use_global=False)
scene=bpy.context.scene
scene.frame_start=0;scene.frame_end=C['frames']-1
scene.render.fps=C['fps'];scene.render.fps_base=1
scene.render.resolution_x=C['width'];scene.render.resolution_y=C['height']
scene.render.resolution_percentage=100
scene.render.engine='BLENDER_EEVEE'
scene.render.use_motion_blur=True;scene.render.motion_blur_shutter=C['shutter']
scene.render.motion_blur_position='CENTER'
scene.world.color=(.16,.16,.16)
coll=H.collection('Example')
body=H.principled('body',C['colors']['body'],metallic=.3,rough=.25)
accent=H.principled('accent',C['colors']['accent'],metallic=.6,rough=.3)
H.rounded_box('housing',(1.2,.25,.6),coll,body,loc=(0,0,.5),bevel=.08)
H.tube_curve('cable',[(-.6,0,.4),(-1,0,1.4),(1,0,1.4),(.6,0,.4)],.035,coll,accent,kind='BEZIER')
H.lathe('control',[(.08,0),(.12,.03),(.12,.10),(.08,.12)],coll,accent,loc=(.8,0,.3),cap_top=True,cap_bottom=True)
atlas=json.loads((ROOT/'display/receipt.json').read_text(encoding='utf8'))
def drive(node):
    for f in range(C['frames']):
        node.outputs[0].default_value=f
        node.outputs[0].keyframe_insert('default_value',frame=f)
mat=H.led_material('display',ROOT/'display/atlas.png',atlas['cols'],atlas['rows'],atlas['tiles'],frame_driver=drive)
grid=H.dot_grid('dots',atlas['cols'],atlas['rows'],.028,coll,mat)
grid.location=(0,-.14,.5)
for name,position,power in [('key',(1,-3,4),500),('rim',(-3,1,3),700)]:
    light=bpy.data.lights.new(name,'AREA');light.energy=power;light.shape='DISK';light.size=3
    obj=bpy.data.objects.new(name,light);coll.objects.link(obj);obj.location=position
    from mathutils import Vector
    obj.rotation_euler=(Vector((0,0,.5))-obj.location).to_track_quat('-Z','Y').to_euler()
cam,aim=H.bake_camera(C['camera_segments'],C['fps'],C['schedule_fps'],C['frames'])
proxy=H.empty('tracking_proxy',coll,loc=(0,0,.5))
H.track_target(aim,proxy,[(0,0),(C['frames']-1,.1)])
(ROOT/'camera_samples.json').write_text(json.dumps(H.camera_samples(),indent=2),encoding='utf8')
